     1	import type {RouteProp} from '@react-navigation/native';
     2	import {useRoute} from '@react-navigation/native';
     3	import type {StackScreenProps} from '@react-navigation/stack';
     4	import React, {useCallback} from 'react';
     5	import {useOnyx} from 'react-native-onyx';
     6	import type {ValueOf} from 'type-fest';
     7	import FullPageNotFoundView from '@components/BlockingViews/FullPageNotFoundView';
     8	import HeaderWithBackButton from '@components/HeaderWithBackButton';
     9	import ScreenWrapper from '@components/ScreenWrapper';
    10	import OptionsList from '@components/OptionsList';
    11	import RadioListItem from '@components/SelectionList/RadioListItem';
    12	import useLocalize from '@hooks/useLocalize';
    13	import * as ReportUtils from '@libs/ReportUtils';
    14	import type {ReportSettingsNavigatorParamList} from '@navigation/types';
    15	import withReportOrNotFound from '@pages/home/report/withReportOrNotFound';
    16	import type {WithReportOrNotFoundProps} from '@pages/home/report/withReportOrNotFound';
    17	import * as ReportActions from '@userActions/Report';
    18	import CONST from '@src/CONST';
    19	import ONYXKEYS from '@src/ONYXKEYS';
    20	import type SCREENS from '@src/SCREENS';
    21	import * as Expensicons from '@src/components/Icon/Expensicons';
    22	import defaultTheme from '@src/styles/theme';
    23	
    24	type NotificationPreferencePageProps = WithReportOrNotFoundProps & StackScreenProps<ReportSettingsNavigatorParamList, typeof SCREENS.REPORT_SETTINGS.NOTIFICATION_PREFERENCES>;
    25	
    26	const greenCheckmark = {src: Expensicons.Checkmark, color: defaultTheme.light.success};
    27	
    28	function NotificationPreferencePage({report}: NotificationPreferencePageProps) {
    29	    const route = useRoute<RouteProp<ReportSettingsNavigatorParamList, typeof SCREENS.REPORT_SETTINGS.NOTIFICATION_PREFERENCES>>();
    30	    const {translate} = useLocalize();
    31	    const [reportNameValuePairs] = useOnyx(`${ONYXKEYS.COLLECTION.REPORT_NAME_VALUE_PAIRS}${report.reportID || -1}`);
    32	    const isMoneyRequestReport = ReportUtils.isMoneyRequestReport(report);
    33	    const currentNotificationPreference = ReportUtils.getReportNotificationPreference(report);
    34	    const shouldDisableNotificationPreferences =
    35	        ReportUtils.isArchivedRoom(report, reportNameValuePairs) ||
    36	        ReportUtils.isSelfDM(report) ||
    37	        (!isMoneyRequestReport && currentNotificationPreference === CONST.REPORT.NOTIFICATION_PREFERENCE.HIDDEN);
    38	    const notificationPreferenceOptions = Object.values(CONST.REPORT.NOTIFICATION_PREFERENCE)
    39	        .filter((pref) => pref !== CONST.REPORT.NOTIFICATION_PREFERENCE.HIDDEN)
    40	        .map((preference) => ({
    41	            value: preference,
    42	            text: translate(`notificationPreferencesPage.notificationPreferences.${preference}`),
    43	            keyForList: preference,
    44	            isSelected: preference === currentNotificationPreference,
    45	            // Include the green checkmark icon to indicate the currently selected value
    46	            customIcon: preference === currentNotificationPreference ? greenCheckmark : null,
    47	        }));
    48	
    49	    const goBack = useCallback(() => {
    50	        ReportUtils.goBackToDetailsPage(report, route.params.backTo);
    51	    }, [report, route.params.backTo]);
    52	
    53	    const updateNotificationPreference = useCallback(
    54	        (value: ValueOf<typeof CONST.REPORT.NOTIFICATION_PREFERENCE>) => {
    55	            ReportActions.updateNotificationPreference(report.reportID, currentNotificationPreference, value, undefined, undefined);
    56	            goBack();
    57	        },
    58	        [report.reportID, currentNotificationPreference, goBack],
    59	    );
    60	
    61	    return (
    62	        <ScreenWrapper
    63	            includeSafeAreaPaddingBottom={false}
    64	            testID={NotificationPreferencePage.displayName}
    65	        >
    66	            <FullPageNotFoundView shouldShow={shouldDisableNotificationPreferences}>
    67	                <HeaderWithBackButton
    68	                    title={translate('notificationPreferencesPage.header')}
    69	                    onBackButtonPress={goBack}
    70	                />
    71	                <OptionsList
    72	                    sections={[{data: notificationPreferenceOptions}]}
    73	                    ListItem={RadioListItem}
    74	                    onSelectRow={(option) => updateNotificationPreference(option.value)}
    75	                    shouldSingleExecuteRowSelect
    76	                    initiallyFocusedOptionKey={notificationPreferenceOptions.find((locale) => locale.isSelected)?.keyForList}
    77	                />
    78	            </FullPageNotFoundView>
    79	        </ScreenWrapper>
    80	    );
    81	}
    82	
    83	NotificationPreferencePage.displayName = 'NotificationPreferencePage';
    84	
    85	export default withReportOrNotFound()(NotificationPreferencePage);
